#include <bits/stdc++.h>using namespace std;#define int long long#define double long double int32_t main() {    ios::sync_with_stdio(false);    cin.tie(0);    cout.tie(0);    int n;    cin >> n;    //! Use Goldbach's conjecture     //? n is prime so we don't need anything    bool is_prime = true;    for (int i = 2; i <= sqrt(n); i++) {        if (n % i == 0) {            is_prime = false;            break;        }    };    if (is_prime) {        cout << 1 << "\n";        return 0;    } //? n is even so we need 2 primes    if (n % 2 == 0) {        cout << 2 << "\n";        return 0;    }    //? so we passed n is prime and n is odd now check if (n - 2) is prime    n -= 2;    is_prime = true;    for (int i = 2; i <= sqrt(n); i++) {        if (n % i == 0) {            is_prime = false;            break;        }    }    if (is_prime)        cout << 2 << '\n';    else        cout << 3 << '\n';}